define("block_exaport/item_blocks",["jquery","jqueryui","core/modal_save_cancel"],function($,JQueryUI,ModalSaveCancel){var config={},updateOrderField=function(){var ids=[];$(".exaport-item-block-list [data-blockid]").each(function(){ids.push(parseInt($(this).attr("data-blockid"),10))}),$("#id_blockorder").val(JSON.stringify(ids))},showChooser=function(){if(!config.hasitem)return void window.alert(config.strings.savefirst);var body='<div class="list-group"><a class="list-group-item list-group-item-action" href="'+config.addurls.text+'">'+config.strings.text+'</a><a class="list-group-item list-group-item-action" href="'+config.addurls.file+'">'+config.strings.file+'</a><a class="list-group-item list-group-item-action" href="'+config.addurls.link+'">'+config.strings.link+'</a><button type="button" class="btn btn-secondary mt-3 exaport-item-block-chooser-cancel">'+config.strings.cancel+"</button></div>";ModalSaveCancel.create({title:config.strings.choosertitle,body:body}).then(function(modal){return modal.getFooter().hide(),modal.getRoot().on("click",".exaport-item-block-chooser-cancel",function(e){e.preventDefault(),modal.hide()}),modal.show(),modal})},initSortable=function(){$(".exaport-item-block-list").length&&($(".exaport-item-block-list").sortable({handle:".exaport-item-block-handle",placeholder:"block-placeholder",forcePlaceholderSize:!0,update:updateOrderField}),updateOrderField())},moveBlock=function(button){var item=button.closest("[data-blockid]");item.length&&("up"===button.data("direction")?item.prev("[data-blockid]").before(item):item.next("[data-blockid]").after(item),updateOrderField())};return{init:function(initconfig){config=initconfig||{},$("body").on("click",".exaport-add-content",function(e){e.preventDefault(),showChooser()}),$("body").on("click",".exaport-item-block-move",function(e){e.preventDefault(),moveBlock($(this))}),initSortable()}}});
